# The Packages section is deliberately collapsed until a visitor asks for it, and
# a click handler reveals it for any link pointing at #packages. That handler only
# fires for clicks on the home page itself.
#
# Every other page's nav and footer says `index.html#packages`. Following one of
# those navigates to the home page with the hash already set, so no click ever
# happens here — the browser looks for #packages, finds a hidden section, and
# leaves the visitor at the top of the page with no packages anywhere. That is
# 40 pages' worth of "Packages" menu items landing on nothing.
patch(
    "index.html",
    "packages open when arrived at via #packages from another page",
    "$$('[data-show-packages]').forEach(b => {\n"
    "  b.setAttribute('aria-expanded','false');\n"
    "  b.setAttribute('aria-controls','packages');\n"
    "  b.onclick = () => showPackages();\n"
    "});",
    "$$('[data-show-packages]').forEach(b => {\n"
    "  b.setAttribute('aria-expanded','false');\n"
    "  b.setAttribute('aria-controls','packages');\n"
    "  b.onclick = () => showPackages();\n"
    "});\n"
    "/* Arriving with the hash already set is not a click, so the handler below\n"
    "   never runs for it. Every nav and footer link on the other 40 pages is\n"
    "   exactly that case. */\n"
    "if(location.hash === '#packages') showPackages();\n"
    "addEventListener('hashchange', () => { if(location.hash === '#packages') showPackages(); });",
)

# Checkout used to create the order in the browser: it invented a reference,
# wrote the package into localStorage and posted a copy to the form handler.
# The order is now created by the server, priced from the server's own
# catalogue, and stored as a row — so the dashboard shows what was actually
# bought, on any browser, and an amount typed by the client cannot be paid.
patch(
    "index.html",
    "checkout creates the order on the server and stores the shortlist",
    "  /* Payment is not connected yet, so this marks the order paid locally and\n     unlocks. The details still reach the office, so nothing is lost in the gap\n     before the gateway is live.\n     PROD: the entitlement is written by the gateway's signed webhook, never\n     here. The database refuses an entitlement without a captured payment. */\n  const ENDPOINT = LAUNCH.formEndpoint || '';\n  if(ENDPOINT){\n    fetch(ENDPOINT, {\n      method: 'POST',\n      headers: {'Content-Type':'application/json','Accept':'application/json'},\n      body: JSON.stringify({\n        form: 'Package purchase (payment not yet connected)',\n        reference: ref, package: buying.name,\n        amount: '\u20b9' + nf.format(gross),\n        gst: '\u20b9' + nf.format(tax),\n        publicUniversities: buying.publicUnis || '',\n        name: buyer.name, phone: buyer.phone, email: buyer.email,\n        consent: buying.consent ? 'yes' : 'not required',\n        consentAt: new Date().toISOString(),\n        consentWording: buying.consent || '',\n        sourcePage: location.pathname, referrer: document.referrer || 'direct',\n        to: LAUNCH.formEmail || ''\n      })\n    }).catch(() => {});\n  }\n\n  unlocked = buying.publicUnis;\n  paidName = buying.name;\n  touched = true;\n  loadUnlocked().then(() => {\n    render();\n    /* Hand the order and the revealed universities to the portal. There is no\n       server yet, so this is how the dashboard knows what was bought.\n       PROD: the order lives in the database and the dashboard reads it from\n       /api/dashboard \u2014 nothing is passed through the browser. */\n    try {\n      localStorage.setItem('glovels_order', JSON.stringify({\n        reference: ref, package: buying.name, publicUnis: buying.publicUnis || 0,\n        grossPaise: gross * 100, name: buyer.name,\n        email: buyer.email, paidAt: new Date().toISOString()\n      }));\n      const shortlist = visibleRows(filtered())\n        .filter(r => !r.locked)\n        .slice(0, 12)\n        .map(r => ({\n          program: r.program, university: r.university, city: r.city,\n          country: r.country, totalInr: r.totalInr, isPublic: r.isPublic,\n          intakes: r.intakes\n        }));\n      localStorage.setItem('glovels_shortlist', JSON.stringify(shortlist));\n    } catch(e) { /* private browsing blocks storage; the dashboard shows samples */ }\n  });\n\n",
    "  /* The order is created by the SERVER, which prices it from its own catalogue.\n     Nothing the browser says about the amount is trusted \u2014 it sends a package id\n     and gets a reference back. The record is a row in the database, so the\n     dashboard reads the real order rather than something this browser remembers.\n     PROD: keep this shape and move the entitlement to the gateway's signed\n     webhook \u2014 the database must refuse an entitlement without a captured\n     payment. */\n  const packageId = buying.id;\n\n  fetch('/api/orders', {\n    method: 'POST',\n    credentials: 'same-origin',\n    headers: {'Content-Type': 'application/json', 'Accept': 'application/json'},\n    body: JSON.stringify({\n      packageId,\n      name: buyer.name, phone: buyer.phone, email: buyer.email,\n      consent: buying.consent ? 'yes' : 'not required',\n      consentWording: buying.consent || '',\n      sourcePage: location.pathname, referrer: document.referrer || 'direct'\n    })\n  })\n  .then(r => r.json().then(d => ({ok: r.ok, d})))\n  .then(({ok, d}) => {\n    if (!ok) throw new Error(d.error || 'order refused');\n    ref = d.reference;                       /* the server's reference, not ours */\n    $('#buyRef') && ($('#buyRef').textContent = ref);\n\n    /* Store the matched universities against the account. This is the shortlist\n       the student sees on their dashboard, on My Universities and on\n       Applications \u2014 one list, on the server, not three copies in a browser. */\n    const ids = visibleRows(filtered()).filter(r => !r.locked).slice(0, 12)\n      .map(r => r.id).filter(Boolean);\n    if (d.linkedToAccount && ids.length) {\n      return fetch('/api/shortlist/bulk', {\n        method: 'POST', credentials: 'same-origin',\n        headers: {'Content-Type': 'application/json'},\n        body: JSON.stringify({ids})\n      }).catch(() => {});\n    }\n    /* Not signed in yet: the order is on file against this email and is claimed\n       the moment they create an account with it, so the shortlist is rebuilt\n       server-side rather than smuggled through localStorage. */\n    try {\n      sessionStorage.setItem('glovels_pending_shortlist', JSON.stringify(ids));\n      sessionStorage.setItem('glovels_pending_email', buyer.email);\n    } catch (e) {}\n  })\n  .catch(() => {\n    /* Server unreachable. The purchase still unlocks the page in front of the\n       visitor and the details are held here, rather than showing an error at the\n       moment somebody has just decided to buy. */\n    try {\n      localStorage.setItem('glovels_order', JSON.stringify({\n        reference: ref, package: buying.name, publicUnis: buying.publicUnis || 0,\n        grossPaise: gross * 100, name: buyer.name, email: buyer.email,\n        paidAt: new Date().toISOString()\n      }));\n    } catch (e) {}\n  });\n\n  unlocked = buying.publicUnis;\n  paidName = buying.name;\n  touched = true;\n  loadUnlocked().then(render);\n\n",
    marker="/api/shortlist/bulk",   # a later patch edits this block; test for this instead
)

